'use strict';
// 隔离源码预览：比较生产画布与重定向目标；不是转场实现。
const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm');
const {randomUUID,createHash}=require('node:crypto');
const root=path.resolve(__dirname,'..'),output=path.join(root,'.workbuddy','p2-production-endpoints-'+randomUUID());
fs.mkdirSync(output);const reportPath=path.join(output,'report.json');
const hash=x=>createHash('sha256').update(x).digest('hex');
const result={status:'incomplete',cases:[],errors:[],limitations:['单页面同任务重复渲染，不冻结浏览器时钟、异步资源或随机，不是双场景同帧。','候选仅将生产管线末端重定向到 RGBA8 目标，不是 HDR 混合、转场或独立后处理实现；画布与目标的编码及 MSAA 可能不同。','比较包含 warpOverlay，但不包含 DOM；仅测试当前浏览器、尺寸和受测场景。','故障为同步 JS 注入，并非真实 context loss 或 GPU 分配失败。']};
function save(){fs.writeFileSync(reportPath,JSON.stringify(result,null,2));}
function once(s,a,b){const i=s.indexOf(a);if(i<0||s.indexOf(a,i+a.length)>=0)throw Error('替换点缺失或不唯一: '+a);return s.slice(0,i)+b+s.slice(i+a.length);}
async function build(){let b=fs.readFileSync(path.join(root,'build.mjs'),'utf8').replace(/\r\n/g,'\n');result.inputHashes=Object.fromEntries(['build.mjs','public/index.html','public/js/app.js','tools/test-deep-models.cjs','space.html','index.html','space-http.html'].map(f=>[f,hash(fs.readFileSync(path.join(root,f)))]));b=once(b,'const ROOT = path.dirname(fileURLToPath(import.meta.url));',`const ROOT = ${JSON.stringify(root)};`);b=once(b,"const app = read('js/app.js');",`const app = read('js/app.js').replace('window.__SE = {', 'window.__SE = { __p: {timeAtLg:cineTimeAtLg,JOURNEY,renderFrame,scene,camera,CS,GLARE,BLOOM,GRADE,getPost:()=>_post},');`);b=once(b,`for (const name of ['space.html', 'index.html']) {\n  fs.writeFileSync(path.join(ROOT, name), htmlOffline);\n}\nfs.writeFileSync(path.join(ROOT, 'space-http.html'), htmlHttp);`,`fs.writeFileSync(${JSON.stringify(path.join(output,'preview.html'))}, htmlOffline, {flag:'wx'});`);await import('data:text/javascript;base64,'+Buffer.from(b).toString('base64'));result.previewSha256=hash(fs.readFileSync(path.join(output,'preview.html')));}
function experiment(fault){
 const s=__SE,p=s.__p,r=s.renderer,T=s.THREE,gl=r.getContext(),cs=p.CS,sc=cs.active?cs.scene:p.scene,cam=cs.active?cs.cam:p.camera;
 const size=r.getDrawingBufferSize(new T.Vector2()),w=size.x,h=size.y,oldTarget=r.getRenderTarget(),face=r.getActiveCubeFace(),mip=r.getActiveMipmapLevel(),originalSet=r.setRenderTarget,originalRender=r.render;
 const target=new T.WebGLRenderTarget(w,h,{depthBuffer:true,stencilBuffer:false});
 const trace=[];let restore=false,thrown='';
 function render(candidate,phase,fail){let outputPixels=new Uint8Array(w*h*4);trace.length=0;
  r.setRenderTarget=function(t,...args){trace.push(t===null?'screen':'target');return originalSet.call(this,candidate&&t===null?target:t,...args);};
  r.render=function(scene,camera,...args){if(fail&&scene===sc)throw Error('injected:scene-draw');return originalRender.call(this,scene,camera,...args);};
  try{p.renderFrame(sc,cam,{gradePhase:phase});if(candidate){originalSet.call(r,target);r.readRenderTargetPixels(target,0,0,w,h,outputPixels);}else{originalSet.call(r,null);gl.readPixels(0,0,w,h,gl.RGBA,gl.UNSIGNED_BYTE,outputPixels);}return {pixels:Array.from(outputPixels),trace:trace.slice(),glError:gl.getError(),lost:gl.isContextLost()};}
  finally{r.setRenderTarget=originalSet;r.render=originalRender;originalSet.call(r,oldTarget,face,mip);}
 }
 try{
  const before=p.getPost().mComp?.uniforms.uGradeT.value??null;
  originalSet.call(r,target);const fboComplete=gl.checkFramebufferStatus(gl.FRAMEBUFFER)===gl.FRAMEBUFFER_COMPLETE;originalSet.call(r,oldTarget,face,mip);
  const a=render(false,42,false),b=render(true,42,false),repeat=render(false,42,false);
  const phase=render(false,43,false);let diff=0,max=0,sum=0,repeatDiff=0,phaseDiff=0;for(let i=0;i<a.pixels.length;i++){const d=Math.abs(a.pixels[i]-b.pixels[i]);if(d)diff++;max=Math.max(max,d);sum+=d;if(a.pixels[i]!==repeat.pixels[i])repeatDiff++;if(a.pixels[i]!==phase.pixels[i])phaseDiff++;}
  if(fault){try{render(true,42,true);}catch(e){thrown=String(e.message||e);}restore=r.setRenderTarget===originalSet&&r.render===originalRender&&r.getRenderTarget()===oldTarget;}
  const after=p.getPost().mComp?.uniforms.uGradeT.value??null,errors=[];for(let i=0;i<8;i++){const e=gl.getError();if(!e)break;errors.push(e);}
  return {size:[w,h],fboComplete,scene:cs.active?'cosmic':'main',post:a.trace.filter(x=>x==='target').length>0,trace:a.trace,candidateTrace:b.trace,comparison:{differentChannels:diff,maxByte:max,meanByte:sum/a.pixels.length,repeatDifferentChannels:repeatDiff,phaseDifferentChannels:phaseDiff},glErrors:[a.glError,b.glError,repeat.glError,phase.glError,...errors].filter(Boolean),lost:gl.isContextLost(),grade:{enabled:p.GRADE.on,before,after},glare:{on:p.GLARE.on,vis:p.GLARE.vis},bloom:{on:p.BLOOM.on},fault:{requested:fault,thrown,restore}};
 }finally{r.setRenderTarget=originalSet;r.render=originalRender;originalSet.call(r,oldTarget,face,mip);target.dispose();}
}
async function run(){await build();const framework=path.join(root,'tools/test-deep-models.cjs');let src=fs.readFileSync(framework,'utf8');const cut=src.indexOf('async function main() {');if(cut<0)throw Error('驱动入口缺失');src=src.slice(0,cut).replace("const profile = fs.mkdtempSync(path.join(parent, 'probe-deep-models-'));","const profile = fs.mkdtempSync(path.join(output, 'chrome-profile-'));");
const driver=`(async()=>{try{await launch();for(const spec of [{scene:'main',lg:19.98,post:false},{scene:'main',lg:19.98,post:true},{scene:'cosmic',lg:20.02,post:false},{scene:'cosmic',lg:20.02,post:true}]){phase=JSON.stringify(spec);await load(pathToFileURL(path.join(output,'preview.html')).href+'?auto=0&q=high&prewarm=0','file');await evaluate('__SE.journey(0);__SE.ts=0;__SE.journeySeek(__SE.__p.timeAtLg('+spec.lg+'));__SE.bloom('+spec.post+');__SE.glare(false);true');await frames(3);const c=await evaluate('('+experiment.toString()+')(true)');c.spec=spec;c.expectedBranch=c.scene===spec.scene&&c.post===spec.post;c.faultCheck=c.fault.thrown==='injected:scene-draw'&&c.fault.restore;result.cases.push(c);save();}result.status=result.cases.length===4&&result.cases.every(c=>c.expectedBranch&&c.faultCheck&&c.fboComplete&&!c.glErrors.length&&!c.lost)?'observed-incomplete':'failed';}catch(e){result.errors.push({phase,error:errorText(e)});result.status='failed';}finally{result.driver={browser:report.browser,gpu:report.gpu,launch:report.launch,errors:report.errors};if(browser){try{cleanupPromise=Promise.resolve();await browser.send('Browser.close');}catch(e){result.errors.push({phase:'关闭浏览器',error:errorText(e)});}browser.ws.close();}else if(child&&child.exitCode===null)child.kill();result.changedInputs=[];for(const [f,h] of Object.entries(result.inputHashes||{}))if(hash(fs.readFileSync(path.join(root,f)))!==h)result.changedInputs.push(f);if(result.changedInputs.length||result.errors.length||report.errors.length)result.status='failed';save();console.log(JSON.stringify({report:reportPath,status:result.status,cases:result.cases.map(c=>({spec:c.spec,branch:c.expectedBranch,comparison:c.comparison,fault:c.fault})),errors:result.errors},null,2));if(result.status==='failed')process.exitCode=1;}})();`;
vm.runInThisContext(`(function(require,__dirname,__filename,process,Buffer,WebSocket,output,result,save,hash,experiment,reportPath,root){${src}\n${driver}\n})`,{filename:framework})(require,__dirname,framework,process,Buffer,WebSocket,output,result,save,hash,experiment,reportPath,root);}
save();run().catch(e=>{result.status='failed';result.errors.push({phase:'构建或初始化',error:e.stack||String(e)});save();console.error(JSON.stringify({report:reportPath,errors:result.errors},null,2));process.exitCode=1;});
